files.src/NcStop.st:
PROGRAM NcStop
VAR_INPUT StartButton AT %I0.0 : BOOL; StopButton AT %I0.1 : BOOL; END_VAR
VAR_OUTPUT Motor AT %Q0.0 : BOOL; StopLamp AT %Q0.1 : BOOL; END_VAR
Motor := StartButton AND StopButton;
StopLamp := NOT StopButton;
END_PROGRAM

